// Timer — a built-in Petal plugin, and the first consumer of the chat API
// (petal.chat, plugins/README.md §2.4). One file, no imports: built-ins are
// buildless so both clients can compile them in with a `?raw` import.
//
//   /timer 5m standup    post "Timer started: standup, 5 min" for everyone,
//                        then "Time's up: standup (5 min)" when it ends
//   /timer 90s           durations: 90s, 5m, 1h, 1h30m, 2m30s, 1:30, or a
//                        bare number of minutes; 1 second to 4 hours
//   /timer list          a private answer listing your running timers
//   /timer cancel [label]  cancel your newest (or the matching) timer
//
// Anything else gets a private usage answer. Timers run in this client, so
// they stop if you leave the meeting; everyone else only sees the chat posts.
// Nothing here reads chat: the plugin sees its own command's text and nothing
// else (permissions: chat:commands, chat:post).

const MAX_MS = 4 * 60 * 60 * 1000;
const MAX_ACTIVE = 3;
const MAX_LABEL = 60;
const USAGE = 'Usage: /timer 5m [label], /timer list, /timer cancel [label]. Durations: 90s, 5m, 1h30m, 1:30, or minutes.';

/** Milliseconds for "90s", "5m", "1h30m", "2m30s", "1:30", or "5" (minutes); null when it is not a duration. */
export function parseDuration(token) {
  const text = String(token || '').trim().toLowerCase();
  let ms = null;
  let m = /^(\d{1,3})$/.exec(text);
  if (m) ms = Number(m[1]) * 60000;
  if (ms === null && (m = /^(\d{1,3}):([0-5]\d)$/.exec(text))) ms = Number(m[1]) * 60000 + Number(m[2]) * 1000;
  if (ms === null && (m = /^(?:(\d{1,2})h)?(?:(\d{1,3})m)?(?:(\d{1,5})s)?$/.exec(text)) && (m[1] || m[2] || m[3])) {
    ms = (Number(m[1] || 0) * 3600 + Number(m[2] || 0) * 60 + Number(m[3] || 0)) * 1000;
  }
  if (ms === null || ms < 1000 || ms > MAX_MS) return null;
  return ms;
}

/** "45 s", "5 min", "1 min 30 s", "1 h 30 min". */
export function humanDuration(ms) {
  const total = Math.round(ms / 1000);
  const h = Math.floor(total / 3600);
  const min = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const parts = [];
  if (h) parts.push(h + ' h');
  if (min) parts.push(min + ' min');
  if (s || parts.length === 0) parts.push(s + ' s');
  return parts.join(' ');
}

/** @type {import('@petal/plugin-sdk').PluginDefinition} */
const definition = {
  activate(petal) {
    /** Newest last. */
    const active = [];

    function labelled(t) {
      return t.label ? t.label + ', ' + humanDuration(t.ms) : humanDuration(t.ms);
    }

    function remove(t) {
      clearTimeout(t.handle);
      const i = active.indexOf(t);
      if (i !== -1) active.splice(i, 1);
    }

    async function start(ms, label) {
      if (active.length >= MAX_ACTIVE) {
        return 'You already have ' + MAX_ACTIVE + ' timers running. Cancel one with /timer cancel.';
      }
      const t = { ms, label, endsAt: Date.now() + ms, handle: null };
      try {
        await petal.chat.post('⏱ Timer started: ' + labelled(t));
      } catch (e) {
        return "Couldn't start the timer: " + ((e && e.message) || 'not in a meeting') + '.';
      }
      t.handle = setTimeout(() => {
        remove(t);
        petal.chat.post("⏱ Time's up: " + (t.label ? t.label + ' (' + humanDuration(t.ms) + ')' : humanDuration(t.ms))).catch(() => {});
      }, ms);
      active.push(t);
      return undefined;
    }

    function list() {
      if (active.length === 0) return 'No timers running. Start one with /timer 5m [label].';
      const now = Date.now();
      return active
        .map((t) => (t.label || 'Timer') + ': ' + humanDuration(Math.max(1000, t.endsAt - now)) + ' left')
        .join(' · ');
    }

    async function cancel(label) {
      const t = label ? [...active].reverse().find((x) => x.label.toLowerCase() === label.toLowerCase()) : active[active.length - 1];
      if (!t) return label ? 'No running timer called "' + label + '".' : 'No timers running.';
      remove(t);
      try {
        await petal.chat.post('⏱ Timer cancelled: ' + labelled(t));
      } catch {
        return 'Timer cancelled.';
      }
      return undefined;
    }

    petal.chat.onCommand('timer', (command) => {
      const args = command.args.trim();
      if (args === '' || args === 'help') return USAGE;
      const [first, ...rest] = args.split(/\s+/);
      const word = first.toLowerCase();
      if (word === 'list') return list();
      if (word === 'cancel' || word === 'stop') return cancel(rest.join(' ').trim());
      const ms = parseDuration(first);
      if (ms === null) return 'Not a duration: "' + first + '". ' + USAGE;
      return start(ms, rest.join(' ').trim().slice(0, MAX_LABEL));
    });
  },
};

export default (globalThis.__petalRegister ? globalThis.__petalRegister(definition) : definition);
